DROP TABLE ETR_SEC_STOCK;

CREATE TABLE "ETR_SEC_STOCK" (
  "PLEDGE_STOCK_ID" varchar2(32) NOT NULL ,
  "PLEDGE_STOCK_NAME" varchar2(100)  ,
  "CREATE_USER" varchar2(20) NOT NULL ,
  "CREATE_DEPT" varchar2(32) ,
  "CREATE_TIME" DATE NOT NULL ,
  "UPDATE_USER" varchar2(20) NOT NULL ,
  "UPDATE_TIME" DATE NOT NULL ,
   CONSTRAINT "PK_ETR_SEC_STOCK" PRIMARY KEY ("PLEDGE_STOCK_ID")
) ;
COMMENT ON COLUMN "ETR_SEC_STOCK"."PLEDGE_STOCK_ID" IS '质押库代码';
COMMENT ON COLUMN "ETR_SEC_STOCK"."PLEDGE_STOCK_NAME" IS '质押库名称';
COMMENT ON COLUMN "ETR_SEC_STOCK"."CREATE_USER" IS '创建人';
COMMENT ON COLUMN "ETR_SEC_STOCK"."CREATE_DEPT" IS '创建部门';
COMMENT ON COLUMN "ETR_SEC_STOCK"."CREATE_TIME" IS '创建时间';
COMMENT ON COLUMN "ETR_SEC_STOCK"."UPDATE_USER" IS '更新人';
COMMENT ON COLUMN "ETR_SEC_STOCK"."UPDATE_TIME" IS '更新时间';

COMMENT ON TABLE "ETR_SEC_STOCK"  IS '债券质押库管理';

DROP TABLE COST_POSITION_DB;
CREATE TABLE "COST_POSITION_DB" (
  "PORTFOLIO_ID" varchar2(32) NOT NULL,
  "FINPROD_ID" varchar2(32) NOT NULL ,
  "CDATE" date NOT NULL ,
  "COST_POSITION" NUMBER(30,14) ,
  "COST_POSITION_NUM" NUMBER(30,14) ,
  "CREATE_USER" varchar2(20) NOT NULL ,
  "CREATE_DEPT" varchar2(32) ,
  "CREATE_TIME" date NOT NULL ,
  "UPDATE_USER" varchar2(20) NOT NULL ,
  "UPDATE_TIME" date NOT NULL ,
  CONSTRAINT "PK_COST_POSITION_DB" PRIMARY KEY ("PORTFOLIO_ID","FINPROD_ID","CDATE")
) ;
COMMENT ON COLUMN "COST_POSITION_DB"."PORTFOLIO_ID" IS '组合代码';
COMMENT ON COLUMN "COST_POSITION_DB"."FINPROD_ID" IS '金融产品代码';
COMMENT ON COLUMN "COST_POSITION_DB"."PORTFOLIO_ID" IS '日期';
COMMENT ON COLUMN "COST_POSITION_DB"."FINPROD_ID" IS '持仓单位成本(综合成本法)';
COMMENT ON COLUMN "COST_POSITION_DB"."PORTFOLIO_ID" IS '持仓数量(综合成本法)';
COMMENT ON COLUMN "COST_POSITION_DB"."CREATE_USER" IS '创建人';
COMMENT ON COLUMN "COST_POSITION_DB"."CREATE_DEPT" IS '创建部门';
COMMENT ON COLUMN "COST_POSITION_DB"."CREATE_TIME" IS '创建时间';
COMMENT ON COLUMN "COST_POSITION_DB"."UPDATE_USER" IS '更新人';
COMMENT ON COLUMN "COST_POSITION_DB"."UPDATE_TIME" IS '更新时间';

COMMENT ON TABLE "COST_POSITION_DB"  IS '组合持仓成本';

DROP TABLE ETR_SEC_STOCK_CONFIG;

CREATE TABLE "ETR_SEC_STOCK_CONFIG" (
  "CONFIG_ID" varchar2(32) NOT NULL ,
  "PLEDGE_STOCK_ID" varchar2(32) ,
  "WINDTYPEONE" varchar2(50) ,
  "WINDTYPETWO" varchar2(50) ,
  "M_GRADE_RESULT" varchar2(50) ,
  "SEC_GRADE_RESULT" varchar2(50) ,
  "IS_SEC_BOND" varchar2(50) ,
  "IS_RIGHT" varchar2(50) ,
  "IS_PPB" varchar2(50) ,
  "CREATE_USER" varchar2(20) NOT NULL ,
  "CREATE_DEPT" varchar2(32) ,
  "CREATE_TIME" DATE NOT NULL ,
  "UPDATE_USER" varchar2(20) NOT NULL ,
  "UPDATE_TIME" DATE NOT NULL ,
  CONSTRAINT "PK_ETR_SEC_STOCK_CONFIG" PRIMARY KEY ("CONFIG_ID")
) ;

COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."CONFIG_ID" IS '设置编号';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."PLEDGE_STOCK_ID" IS '质押库编号';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."WINDTYPEONE" IS '资产一级分类';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."WINDTYPETWO" IS '资产二级分类';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."M_GRADE_RESULT" IS '主体评级';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."SEC_GRADE_RESULT" IS '债项评级';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."IS_SEC_BOND" IS '是否次级债';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."IS_RIGHT" IS '是否含权债';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."IS_PPB" IS '是否私募债';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."CREATE_USER" IS '创建人';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."CREATE_DEPT" IS '创建部门';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."CREATE_TIME" IS '创建时间';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."UPDATE_USER" IS '更新人';
COMMENT ON COLUMN "ETR_SEC_STOCK_CONFIG"."UPDATE_TIME" IS '更新时间';

COMMENT ON TABLE "ETR_SEC_STOCK_CONFIG"  IS '债券自动入库设置';

