COMMENT ON COLUMN "PTL_SEC_STOCK"."CREATE_DEPT" IS '创建部门';
COMMENT ON COLUMN "PTL_SEC_STOCK"."CREATE_TIME" IS '创建时间';
COMMENT ON COLUMN "PTL_SEC_STOCK"."UPDATE_USER" IS '更新人';
